            output[r][c] = 5
        elif r + c == 36:
            output[r][c] = 3
        elif r + c == 50:
            output[r][c] = 3
        elif r + c == 52:
            output[r][c] = 4

# Verify dimensions
print(f"Grid dimensions: {len(output)}x{len(output[0])}")

# Count by value
from collections import Counter
counts = Counter()
for row in output:
    for cell in row:
        counts[cell] = counts.get(cell, 0) + 1

nonzero = {k: v for k, v in counts.items() if k > 0}
print(f"Non-zero counts: {nonzero}")

# Print grid as string to verify
print("\nGrid preview:")
for row_idx, row in enumerate(output):
    row_str = " ".join(str(cell) for cell in row)
    # Show only rows with non-zero
    if any(c > 0 for c in row):
        print(f"Row {row_idx:2d}: {row_str}")

output_json = json.dumps(output)
