# Add anti-diagonals
for r in range(height):
    for c in range(width):
        if r + c == 9:
            output[r][c] = 1
        elif r + c == 28:
            output[r][c] = 5
        elif r + c == 36:
            output[r][c] = 3
        elif r + c == 50:
            output[r][c] = 3
        elif r + c == 52:
            output[r][c] = 4

# Build JSON string directly
grid_json = '[' + ',\n '.join(
    '[' + ', '.join(str(x) for x in row) + ']' 
    for row in output
) + ']'

print(f"Grid shape: {len(output)}x{len(output[0])}")

# Save for later use
with open('/tmp/final_grid.json', 'w') as f:
    f.write(grid_json)

# Also verify first and last few rows of the grid
print("\nFirst 5 rows:")
for row in output[:5]:
    print(row)

print("\nLast 5 rows:")
for row in output[-5:]:
    print(row)

